k11_temp.FC_Sturm:
FUNCTION "FC_Sturm" : Void
VAR_INPUT
   Wind_kmh : Int;
END_VAR
VAR_OUTPUT
   Warnung : Bool;
   Stopp : Bool;
END_VAR
VAR_TEMP
   Sturm : Bool;   // Zwischenergebnis
END_VAR
BEGIN
NETWORK Sturm erkennen
[#Wind_kmh > 60] => #Sturm;

NETWORK Abschalten
#Sturm => #Stopp;

NETWORK Warnen
#Sturm OR [#Wind_kmh >= 40] => #Warnung;
END_FUNCTION

