k11_boss.FC_Station:
FUNCTION "FC_Station" : Void
VAR_INPUT
   Tuer_Zu : Bool;
   Seil_OK : Bool;
   Not_Halt_OK : Bool;
   Wind_kmh : Int;
   S_Start : Bool;
END_VAR
VAR_OUTPUT
   Freigabe : Bool;
   Antrieb_Ein : Bool;
   Windwarnung : Bool;
END_VAR
BEGIN
NETWORK Freigabe
#Tuer_Zu AND #Seil_OK AND #Not_Halt_OK AND [#Wind_kmh <= 60] => #Freigabe;

NETWORK Antrieb
#Freigabe AND #S_Start => #Antrieb_Ein;

NETWORK Windwarnung
[#Wind_kmh > 40] => #Windwarnung;
END_FUNCTION
